//! This crate's screens as Screen Compiler converts them, exactly as it
//! wrote them, each with a function that builds it on a real `nowayos-ui`
//! tree. Generated by Screen Compiler's tools/screens: do not edit by hand.

use nowayos_ui::{NodeId, Tree, UiError};

/// Nodes a screen may use: more than any converted screen needs.
pub const CAPACITY: usize = 96;

/// Bytes of long text a screen may hold (builder contract v16): more than
/// any converted screen needs.
pub const TEXT: usize = 4096;

/// Builds a screen on a real tree and returns its root node.
pub type Build = fn(&mut Tree<CAPACITY, TEXT>) -> Result<NodeId, UiError>;

/// Every converted screen: its file's name and the function that builds it.
#[rustfmt::skip]
pub const SCREENS: &[(&str, Build)] = &[
    ("hello", build_hello),
    ("welcome", build_welcome),
];

/// `hello.tsx`, converted by Screen Compiler.
pub mod hello {
    include!("hello.rs");
}

/// Builds `hello.tsx`'s screen `hello_screen` on a real tree.
///
/// # Errors
///
/// The tree's error, if the screen does not fit it.
pub fn build_hello(tree: &mut Tree<CAPACITY, TEXT>) -> Result<NodeId, UiError> {
    hello::hello_screen::build(tree).map(|nodes| nodes.root)
}

/// `welcome.tsx`, converted by Screen Compiler.
pub mod welcome {
    include!("welcome.rs");
}

/// Builds `welcome.tsx`'s screen `welcome_screen` on a real tree.
///
/// # Errors
///
/// The tree's error, if the screen does not fit it.
pub fn build_welcome(tree: &mut Tree<CAPACITY, TEXT>) -> Result<NodeId, UiError> {
    welcome::welcome_screen::build(tree).map(|nodes| nodes.root)
}
